import{_ as t,o,c as e,ag as a}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年9月23日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-23.md","filePath":"science-log/src/reconstructed/2026-09-23.md"}'),n={name:"science-log/src/reconstructed/2026-09-23.md"};function s(i,r,g,u,l,h){return o(),e("div",null,[...r[0]||(r[0]=[a('<h1 id="🔬-科学快报-2026年9月23日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月23日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月23日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月23日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef — Nature <code>0028-0836</code>（当日总命中 108 条，研究论文取 <code>10.1038/s41586-…</code>）、PNAS <code>0027-8424</code>（命中 19 条）；arXiv <code>cat:cs.AI</code> 日期区间 <code>[202609230000 TO 202609232359]</code>（命中 40 篇）｜ 重建日：2026-11-05 说明：当日投给 <code>prefixes/10.1126</code>（Science 系）的命中其 <code>published</code> 均为 2026-09-24 刊期，为避免与 09-24 期重复，本期科学 5 篇全部取自同日 Nature / PNAS 的真实研究论文。</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧠-人前额叶皮层全生命周期单细胞转录组图谱" tabindex="-1">🧠 人前额叶皮层全生命周期单细胞转录组图谱 <a class="header-anchor" href="#🧠-人前额叶皮层全生命周期单细胞转录组图谱" aria-label="Permalink to &quot;🧠 人前额叶皮层全生命周期单细胞转录组图谱&quot;">​</a></h3><p><strong>Lifespan single-cell transcriptomic atlas of the human prefrontal cortex</strong><em>Nature（2026-09-23）</em></p><p>背外侧前额叶（DLPFC）主管高级认知、又对衰老格外敏感，但以往单细胞研究多局限于某一年龄段或患病脑，无法把&quot;正常发育/衰老轨迹&quot;与&quot;病理过程&quot;分开。Hui Yang 等（含 PsychAD Consortium，共 69 位作者）构建了覆盖人类<strong>全生命周期</strong>的单核转录组图谱，发现 DLPFC 的转录轨迹是<strong>非线性、细胞类型特异</strong>的：发育期动态重塑、中年相对稳定、晚年出现选择性分子&quot;再激活&quot;，并识别出早期神经元的&quot;韧性&quot;通路（early-life neuronal resilience pathways）以及晚年阶段的分子变化等不同神经元与胶质程序。这为解读正常衰老及其与精神、神经退行性疾病的关联提供了带生命周期分辨率的参考系。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10271-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10271-7</a></p><h3 id="⚡-cvd-生长的-1h-堆叠-mos2-双层出现-直接带隙" tabindex="-1">⚡ CVD 生长的 1H 堆叠 MoS₂ 双层出现&quot;直接带隙&quot; <a class="header-anchor" href="#⚡-cvd-生长的-1h-堆叠-mos2-双层出现-直接带隙" aria-label="Permalink to &quot;⚡ CVD 生长的 1H 堆叠 MoS₂ 双层出现&quot;直接带隙&quot;&quot;">​</a></h3><p><strong>Stacking-induced direct band gap in CVD-grown 1H MoS2 bilayers</strong><em>Nature（2026-09-23）</em></p><p>双层过渡金属硫属化物（TMD）载流子迁移率更高、极性可电控，是新一代晶体管与滑动铁电器件的候选，但其<strong>本征间接带隙</strong>严重限制发光，难以进入光电器件。Tilo H. Yang 等（19 位作者）用<strong>两步化学气相沉积</strong>得到原子级精确垂直对齐的 <strong>1H 堆叠</strong> MoS₂ 双层，由角分辨光电子能谱与密度泛函计算共同确认具有<strong>直接带隙</strong>；光致发光显示激子发射增强、间接带隙特征消失，且共振与非共振激发下的<strong>区域（valley）极化都强于单层</strong>，主因是顶层区间散射被抑制。这把&quot;堆叠方式&quot;确立为调控量子材料的独立自由度，指向谷电子学与光电子学应用。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-11069-3" target="_blank" rel="noreferrer">10.1038/s41586-026-11069-3</a></p><h3 id="🧬-tsc2-缺失-细胞自主-地把神经前体细胞推向反应性星形胶质细胞" tabindex="-1">🧬 TSC2 缺失&quot;细胞自主&quot;地把神经前体细胞推向反应性星形胶质细胞 <a class="header-anchor" href="#🧬-tsc2-缺失-细胞自主-地把神经前体细胞推向反应性星形胶质细胞" aria-label="Permalink to &quot;🧬 TSC2 缺失&quot;细胞自主&quot;地把神经前体细胞推向反应性星形胶质细胞&quot;">​</a></h3><p><strong>mTORC1 drives cell-autonomous astrocyte reactivity in tuberous sclerosis</strong><em>Nature（2026-09-23）</em></p><p>结节性硬化症（TSC）的皮层结节伴随严重难治性癫痫，结节中常见胶质异常，但&quot;胶质是主动致病，还是慢性癫痫的后果&quot;长期不清。Thomas L. Li、John D. Blair、Helen S. Bateup 等 7 位作者用<strong>人脑类器官</strong>在<strong>无癫痫</strong>条件下追踪突变前体细胞的发育命运，并结合患者切除结节组织的单细胞转录组与循环免疫染色证明：<strong>TSC2 缺失以细胞自主方式</strong>把神经前体细胞偏向分化成<strong>体积增大、促炎的反应性星形胶质细胞</strong>——其谷氨酸转运体表达下调、炎症因子分泌增加，并上调 APOE、CLU 等神经退行性疾病风险基因。反应性星形胶质细胞由此被确立为 TSC2 缺失的<strong>原发性后果</strong>，把胶质功能障碍推为 TSC 发病的驱动因素。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-11054-w" target="_blank" rel="noreferrer">10.1038/s41586-026-11054-w</a></p><h3 id="🔥-微气泡沸腾的真相-临界热流不是终点-而是分岔点" tabindex="-1">🔥 微气泡沸腾的真相：临界热流不是终点，而是分岔点 <a class="header-anchor" href="#🔥-微气泡沸腾的真相-临界热流不是终点-而是分岔点" aria-label="Permalink to &quot;🔥 微气泡沸腾的真相：临界热流不是终点，而是分岔点&quot;">​</a></h3><p><strong>Microbubble emission boiling reinterpreted: Condensation-driven oscillations enable heat transfer beyond the critical heat flux</strong><em>PNAS（2026-09-23）</em></p><p>经典理论把临界热流（CHF）视为&quot;汽膜覆盖、传热崩溃&quot;的终极阈值，但在强过冷水中早已观测到<strong>微气泡沸腾（MEB）<strong>能维持超越该极限的热流，其物理起源自 1980 年代以来争论不休。Jiazheng Liu、Jiayi Zhang、Duoqi Liu 等用近壁温度测量、本征示踪粒子速度场与压力谱，发现 CHF 背后的流体动力学不稳定性其实是一个</strong>分岔点</strong>：过冷足够时<strong>快速冷凝拦截汽泡聚并</strong>，把失稳后的演化引向高频、塌缩驱动的对流，即作者命名的&quot;冷凝驱动振荡沸腾（COB）&quot;，其振荡时标定量地重现了超过 <strong>1.4 kW cm⁻²</strong> 的持续宏观热流。作者进一步给出无量纲判据 <strong>Π &lt; 1</strong>（冷凝与聚并的时间尺度竞争）来区分膜态沸腾与 COB，并用迟滞实验证明该支路可重复稳定。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2612649123" target="_blank" rel="noreferrer">10.1073/pnas.2612649123</a></p><h3 id="🧊-液态里的-取向前驱体-决定析出哪种晶型" tabindex="-1">🧊 液态里的&quot;取向前驱体&quot;决定析出哪种晶型 <a class="header-anchor" href="#🧊-液态里的-取向前驱体-决定析出哪种晶型" aria-label="Permalink to &quot;🧊 液态里的&quot;取向前驱体&quot;决定析出哪种晶型&quot;">​</a></h3><p><strong>Liquid-state orientational precursors bias crystal polymorph nucleation</strong><em>PNAS（2026-09-23）</em></p><p>过冷液体常常先析出<strong>并非热力学最稳定</strong>的晶型，仅靠统计涨落或体相自由能层级无法解释这种&quot;多晶型选择&quot;。Simin An、Pengfei Guan、Xian Zhang 等对过冷 Cu、Al 与 Lennard-Jones 液体做分子动力学模拟，发现成核初期的多晶型选择由液体中的<strong>取向有序前驱体态</strong>偏置：<strong>空间相干性更强、更持久</strong>的前驱体组分，更容易促成<strong>对称性相容</strong>、或可经<strong>低势垒跨对称变换</strong>到达的晶体结构——即便这些结构不对应最稳定的体相。由于前驱体<strong>缺乏平移序</strong>，其在液态中的取向对称性可以不同于平衡晶体，从而创造出基于体相自由能与液—晶界面张力这类宏观描述所捕捉不到的成核路径。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2601278123" target="_blank" rel="noreferrer">10.1073/pnas.2601278123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🧠-给世界模型-补上-客体永久性" tabindex="-1">🧠 给世界模型&quot;补上&quot;客体永久性 <a class="header-anchor" href="#🧠-给世界模型-补上-客体永久性" aria-label="Permalink to &quot;🧠 给世界模型&quot;补上&quot;客体永久性&quot;">​</a></h3><p><strong>Training Object Permanence in World Models</strong><em>arXiv（2026-09-23）</em></p><p>客体永久性与实体性是人类的认知先验，而视频生成模型作为一类&quot;世界模型&quot;是否已涌现这些能力，此前并不清楚。Haotian Zhang、Fengyuan Yu、Dezhi Luo 等 31 位作者提出 <strong>WROP</strong>（World Reasoning with Object Permanence）：150 个受认知科学启发的任务、分为六大认知类别，用 Blender 生成器在随机化速度、光照、机位等干扰参数的同时<strong>保持每个任务的认知结构</strong>，每任务产出 10,000+ 样本，并发布 150 万条训练语料与一份 300 题考卷。在这份考卷上评测 14 个视频模型（3 个参考—视频、7 个编辑、4 个续写）后，他们训练的 16B 世界模型 PWM-WROP 在盲测成对 Elo 研究中位列续写类第一、总体第三。这条路把&quot;物理智能&quot;的评测从观感引向可设计的认知任务。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.28654" target="_blank" rel="noreferrer">2609.28654</a></p><h3 id="📄-智能体能不能复现机器学习论文" tabindex="-1">📄 智能体能不能复现机器学习论文？ <a class="header-anchor" href="#📄-智能体能不能复现机器学习论文" aria-label="Permalink to &quot;📄 智能体能不能复现机器学习论文？&quot;">​</a></h3><p><strong>RECLAIM: Can Agents Reproduce the Claims of Machine Learning Papers?</strong><em>arXiv（2026-09-23）</em></p><p>复现一篇机器学习论文几乎涵盖从装软件、调试到跑实验的全部研究步骤，而这些工作正越来越多地交给 AI 智能体。Mithil Salunkhe、Haochen Ding、Samridhi Verma、Volodymyr Kindratenko 提出 <strong>RECLAIM</strong> 基准：100 篇 NeurIPS 2025 论文（可按年从新会议重建），每篇<strong>事先固定</strong>要复现的结果、成功判据与 GPU 小时预算；难度按作者放出的材料分档——Run（有代码/数据/权重）、Retrain（缺权重，需自行训练）、Reimplement（缺代码，需自行实现），并由一个独立的语言模型<strong>依据日志与输出、而非智能体的自述报告</strong>打分。结论冷静：各档最优智能体仅复现 <strong>41% / 27% / 15%</strong>，失败尝试平均只用掉 29% 预算（多数在预算未尽时停下），最常见的错误与&quot;写错（实现错误）&quot;相关。它为&quot;AI 研究员&quot;叙事提供了可复现的刻度尺。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.28850" target="_blank" rel="noreferrer">2609.28850</a></p><h3 id="🎓-ai-辅导与人类专家辅导-gre-学习增益相当" tabindex="-1">🎓 AI 辅导与人类专家辅导，GRE 学习增益相当 <a class="header-anchor" href="#🎓-ai-辅导与人类专家辅导-gre-学习增益相当" aria-label="Permalink to &quot;🎓 AI 辅导与人类专家辅导，GRE 学习增益相当&quot;">​</a></h3><p><strong>StudentBench: AI and human tutoring yield equivalent GRE learning gains</strong><em>arXiv（2026-09-23）</em></p><p>Curtis Northcutt、Inaara Hasmani、Kevin Feng 等构建 <strong>StudentBench</strong> 教学评测套件与公开平台，采集超过 <strong>175,000</strong> 条学生—AI 消息，并在 <strong>2,383 名人类参与者</strong>中比较&quot;AI 辅导 / 人类辅导 / 不辅导&quot;三种条件下定量与语文 GRE 题目的学习增益。核心结论是：<strong>AI 辅导的学习增益与专家人类辅导统计等价</strong>（p = .015），且在 7 个 GRE 子域中有 5 个、表现最好的 AI 辅导者平均超过人类辅导者。第二项研究中，专家人类辅导者通过 <strong>2,028 次成对评分</strong>比较了 LLM 生成的教案与练习题。两项研究合起来把 AI 辅导者按&quot;备课 / 出题 / 对话&quot;等能力维度清晰区分开来。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.28470" target="_blank" rel="noreferrer">2609.28470</a></p><h3 id="🔍-可验证奖励也能训练-小规模-搜索智能体" tabindex="-1">🔍 可验证奖励也能训练&quot;小规模&quot;搜索智能体 <a class="header-anchor" href="#🔍-可验证奖励也能训练-小规模-搜索智能体" aria-label="Permalink to &quot;🔍 可验证奖励也能训练&quot;小规模&quot;搜索智能体&quot;">​</a></h3><p><strong>Reinforcement Learning with Verifiable Rewards for Small Search Agents</strong><em>arXiv（2026-09-23）</em></p><p>&quot;推理—检索&quot;配方把 RLVR 用到开放域问答（检索为答案提供依据、与参考答案匹配即给奖励），但此前只在<strong>大模型</strong>上被验证，低于 10 亿参数时仅靠更大教师模型的蒸馏。Gaurisankar Jayadas、Aske Plaat 等直接在<strong>小模型</strong>上测试该配方：用 GRPO 训练 Qwen3.5-0.8B，配一个<strong>交错的维基百科搜索工具</strong>，在 MuSiQue 上只改奖励形状、每种形状三个种子，并把每个检查点留出评测于一个七基准问答套件。配方成立——最佳一次平均精确匹配达 <strong>0.352</strong>，对比未训练下限 <strong>0.092</strong>，即 <strong>3.8 倍</strong>提升，且训练回路中<strong>不含任何蒸馏步骤</strong>。同时奖励形状很要紧：忠实照搬 Search-R1 的&quot;只看精确匹配&quot;奖励，在<strong>每一个种子上都是三者中最差</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.28765" target="_blank" rel="noreferrer">2609.28765</a></p><h3 id="🧮-顺序无关的答案-顺序敏感的表示" tabindex="-1">🧮 顺序无关的答案，顺序敏感的表示 <a class="header-anchor" href="#🧮-顺序无关的答案-顺序敏感的表示" aria-label="Permalink to &quot;🧮 顺序无关的答案，顺序敏感的表示&quot;">​</a></h3><p><strong>Order-Invariant Answers, Order-Sensitive Representations in Mathematical Reasoning</strong><em>arXiv（2026-09-23）</em></p><p>重排一组数学规则而不改变其含义时，正确答案应当保持不变——但模型的<strong>内部表示</strong>也必须不变吗？Zhixu Silvia Tao（单作者）用合成的多步函数复合问题研究此问：同一问题以多种规则顺序呈现、正确答案相同，同时测量准确率与<strong>排列信噪比</strong>（ordering patterns 相对于题目间差异被表示得有多清晰）。在从小到大的 <strong>16 个语言模型（1B–8B）<strong>中浮现出一条规律：<strong>越能正确解答乱序问题的模型，越把不同的规则顺序表示得彼此分明</strong>；层平均排列信噪比在所有合成设置中都</strong>正相关于准确率</strong>，Spearman 相关最高达 <strong>0.86</strong>。由此区分出&quot;<strong>答案不变性</strong>&quot;与&quot;<strong>表示不变性</strong>&quot;——成功的数学规则复合可以伴随彼此有别的内部表示，这是关于推理表征的一个可证伪的新维度。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.28442" target="_blank" rel="noreferrer">2609.28442</a></p><blockquote><p>📅 日期：2026-09-23 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const d=t(n,[["render",s]]);export{p as __pageData,d as default};
